# Quisk hardware file for simple Tayloe-based SDR receiver ("SimpleSDR")
# whose quadrature LO is generated by a Raspberry Pi Pico running grug_lo_gen.
#
# The Pico is controlled over its USB serial port: send "<freq in Hz>\r",
# it answers with the actual frequency it managed, e.g. "1290079\r\n".
#
# SERIAL_PORT: set to e.g. "COM10" on Windows, "/dev/ttyACM0" on Linux or
# "/dev/cu.usbmodem23401" on macOS.  Leave it as None to auto-detect the
# first USB modem port (works on macOS and Linux).

from __future__ import absolute_import
import glob
import serial

from quisk_hardware_model import Hardware as BaseHardware

SERIAL_PORT = None

def find_serial_port():
  if SERIAL_PORT:
    return SERIAL_PORT
  for pattern in ("/dev/cu.usbmodem*", "/dev/ttyACM*"):
    ports = sorted(glob.glob(pattern))
    if ports:
      return ports[0]
  return None

class Hardware(BaseHardware):
  def __init__(self, app, conf):
    BaseHardware.__init__(self, app, conf)
    self.sp = None
    self.vfo = self.conf.fixed_vfo_freq		# Fixed VFO frequency in Hertz
    self.tune = self.vfo + 10000		# Current tuning frequency in Hertz

  def open(self):
    port = find_serial_port()
    try:
      self.sp = serial.Serial(port, 115200, timeout=2)
    except Exception as e:
      self.sp = None
      return "SimpleSDR: serial port %s open failed: %s" % (port, e)
    # Put the Pico on the configured VFO right away so the display is correct at startup.
    self.vfo = self.SetPicoFreq(self.vfo)
    return "SimpleSDR: Pico on %s, LO %d Hz" % (port, self.vfo)

  def close(self):
    if self.sp:
      self.sp.close()
      self.sp = None

  def SetPicoFreq(self, freq):
    # Send the LO frequency to the Pico and return the actual frequency it set.
    if not self.sp:
      return freq
    self.sp.reset_input_buffer()
    self.sp.write(("%d\r" % int(freq)).encode("ascii"))
    resp = self.sp.readline()
    try:
      return int(resp)
    except ValueError:
      print("SimpleSDR: bad response from Pico:", resp)
      return freq

  def ChangeFrequency(self, tune, vfo, source='', band='', event=None):
    # Keep the VFO fixed while the tuning frequency stays inside the displayed
    # band; otherwise move the LO so the signal lands 10 kHz above it.
    self.tune = tune
    half = self.conf.sample_rate // 2
    if source == 'BtnBand' or vfo != self.vfo:
      # Band button or user changed the VFO directly.
      self.vfo = self.SetPicoFreq(vfo)
    elif tune > self.vfo + half or tune < self.vfo - half:
      self.vfo = self.SetPicoFreq(tune - 10000)
    return tune, self.vfo

  def ReturnFrequency(self):
    return None, None
